const seed={members:[{id:'alex',name:'Alex Morgan',initials:'AM',role:'Leader',color:'#6657bd'},{id:'mia',name:'Mia Chen',initials:'MC',role:'Product',color:'#277b85'},{id:'noah',name:'Noah Williams',initials:'NW',role:'Engineering',color:'#a45c78'},{id:'sofia',name:'Sofia Petrović',initials:'SP',role:'Design',color:'#b6774e'}],tasks:[{id:1,title:'Finalize Q4 launch plan',priority:'High',status:'progress',assignee:'alex',dueDate:'2026-11-15',description:'Align the team around the final launch sequence.'},{id:2,title:'Review onboarding flow',priority:'Medium',status:'review',assignee:'mia',dueDate:'2026-11-17',description:'Check the latest onboarding screens.'},{id:3,title:'Ship analytics events',priority:'High',status:'progress',assignee:'noah',dueDate:'2026-11-16',description:'Add the remaining product analytics events.'},{id:4,title:'Update brand guidelines',priority:'Low',status:'backlog',assignee:'sofia',dueDate:'2026-11-21',description:'Refresh the internal brand reference.'},{id:5,title:'Write release notes',priority:'Medium',status:'done',assignee:'alex',dueDate:'2026-11-12',description:'Summarize the latest product changes.'},{id:6,title:'Customer feedback synthesis',priority:'Low',status:'done',assignee:'mia',dueDate:'2026-11-11',description:'Cluster themes from the latest interviews.'},{id:7,title:'QA mobile navigation',priority:'Medium',status:'backlog',assignee:'noah',dueDate:'2026-11-20',description:'Run through the mobile navigation checklist.'}]};
let state=JSON.parse(localStorage.getItem('orbit-workspace'))||seed; const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)]; const initials=id=>state.members.find(m=>m.id===id)?.initials||'??'; const member=id=>state.members.find(m=>m.id===id)||state.members[0];
const statuses=[['backlog','Backlog'],['progress','In progress'],['review','Review'],['done','Done']];
function save(){localStorage.setItem('orbit-workspace',JSON.stringify(state))} function icon(){lucide.createIcons()} function formatDate(d){if(!d)return 'No due date';const date=new Date(`${d}T12:00:00`);return date.toLocaleDateString('en-US',{month:'short',day:'numeric'})} function toast(msg){$('#toast span').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function renderKpis(){const t=state.tasks,done=t.filter(x=>x.status==='done').length,over=t.filter(x=>x.dueDate&&new Date(x.dueDate)<new Date('2026-11-14')&&x.status!=='done').length;$('#kpiGrid').innerHTML=[['Total tasks',t.length,'+12% from last week','layout-list','#29233f'],['Completed',done,'+8.4% from last week','circle-check','#173a32'],['In progress',t.filter(x=>x.status==='progress').length,'2 due this week','loader-circle','#19383d'],['Overdue',over,'Needs attention','triangle-alert','#3b232d']].map(([a,b,c,ic,bg],i)=>`<article class="kpi-card"><div class="kpi-top"><span>${a}</span><span class="kpi-icon" style="background:${bg};color:${i===3?'#ff7d92':i===1?'#70d6a4':i===2?'#61d8de':'#a796ff'}"><i data-lucide="${ic}"></i></span></div><div class="kpi-value">${b}</div><div class="kpi-meta ${i===3?'down':'up'}">${c}</div></article>`).join('');$('#myTaskBadge').textContent=t.filter(x=>x.assignee==='alex'&&x.status!=='done').length;icon()}
function renderChart(){const data=state.members.map(m=>{const ts=state.tasks.filter(t=>t.assignee===m.id);return {m,done:ts.filter(t=>t.status==='done').length,progress:ts.filter(t=>t.status==='progress'||t.status==='review').length,remaining:ts.filter(t=>t.status==='backlog').length}});$('#workloadChart').innerHTML=data.map(x=>`<div class="bar-group"><div class="bar completed" style="height:${Math.max(8,x.done*28)}px"></div><div class="bar progress" style="height:${Math.max(8,x.progress*28)}px"></div><div class="bar remaining" style="height:${Math.max(8,x.remaining*28)}px"></div><span class="bar-label">${x.m.initials}</span></div>`).join('')}
function renderActivity(){const events=[['MC','Mia moved “Review onboarding flow” to Review','12 min ago','#277b85'],['NW','Noah was assigned “Ship analytics events”','38 min ago','#a45c78'],['AM','You completed “Write release notes”','1 hr ago','#6657bd'],['SP','Sofia joined the workspace','3 hrs ago','#b6774e']];$('#activityList').innerHTML=events.map(e=>`<div class="activity"><div class="avatar activity-avatar" style="background:${e[3]}">${e[0]}</div><div class="activity-copy">${e[1]}<span class="activity-time">${e[2]}</span></div></div>`).join('')}
function taskCard(t){const m=member(t.assignee),over=t.dueDate&&new Date(t.dueDate)<new Date('2026-11-14')&&t.status!=='done';return `<article class="task-card" draggable="true" data-id="${t.id}"><div class="task-top"><span class="priority ${t.priority}">${t.priority.toUpperCase()}</span><button class="more-button task-menu"><i data-lucide="more-horizontal"></i></button></div><div class="task-title">${t.title}</div><div class="task-bottom"><span class="task-due ${over?'overdue':''}"><i data-lucide="calendar-days"></i>${formatDate(t.dueDate)}</span><span class="avatar task-assignee" style="background:${m.color}" title="${m.name}">${m.initials}</span></div></article>`}
function renderBoard(){let filtered=state.tasks; const board=$('#board');board.innerHTML=statuses.map(([key,label])=>`<div class="column" data-status="${key}"><div class="column-header"><span class="column-title">${label}</span><span class="column-count">${filtered.filter(t=>t.status===key).length}</span></div>${filtered.filter(t=>t.status===key).map(taskCard).join('')}<button class="add-task-button" data-add-status="${key}">+ Add task</button></div>`).join(''); $$('.task-card').forEach(card=>{card.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',card.dataset.id));card.addEventListener('click',e=>{if(!e.target.closest('.task-menu'))openTask(card.dataset.id)})});$$('.column').forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('drop-target')});col.addEventListener('dragleave',()=>col.classList.remove('drop-target'));col.addEventListener('drop',e=>{e.preventDefault();const t=state.tasks.find(x=>x.id==e.dataTransfer.getData('text/plain'));if(t){t.status=col.dataset.status;save();render();toast('Task status updated')}})});$$('.add-task-button').forEach(b=>b.onclick=()=>openModal(b.dataset.addStatus));icon()}
function renderLists(){const list=(items,container)=>$(container).innerHTML=items.map(t=>`<div class="simple-item"><span class="avatar task-assignee" style="background:${member(t.assignee).color}">${initials(t.assignee)}</span><span><strong>${t.title}</strong><small>${member(t.assignee).name} · ${formatDate(t.dueDate)}</small></span><span class="priority ${t.priority}">${t.priority}</span></div>`).join('');list(state.tasks.filter(t=>t.assignee==='alex'), '#myTaskList');list(state.tasks,'#teamTaskList');$('#membersList').innerHTML=state.members.map(m=>`<div class="member-item"><span class="avatar member-avatar" style="background:${m.color}">${m.initials}</span><span class="member-info"><strong>${m.name}</strong><span>${m.role}</span></span><span class="kpi-meta">${state.tasks.filter(t=>t.assignee===m.id&&t.status!=='done').length} active</span></div>`).join('')}
function render(){renderKpis();renderChart();renderActivity();renderBoard();renderLists()}
function openModal(status='progress'){const form=$('#taskForm');form.reset();form.elements.status.value=status;$('#assigneeSelect').innerHTML=state.members.map(m=>`<option value="${m.id}">${m.name}</option>`).join('');$('#modalBackdrop').classList.add('open');setTimeout(()=>form.elements.title.focus(),50)} function closeModal(){$('#modalBackdrop').classList.remove('open')}
function openTask(id){const t=state.tasks.find(x=>x.id==id);if(!t)return;openModal(t.status);const f=$('#taskForm');f.title.value=t.title;f.assignee.value=t.assignee;f.priority.value=t.priority;f.dueDate.value=t.dueDate;f.description.value=t.description||'';f.dataset.editing=id;f.querySelector('[type=submit]').innerHTML='<i data-lucide="save"></i> Save changes';icon()}
$('#taskForm').addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));if(f.dataset.editing){Object.assign(state.tasks.find(t=>t.id==f.dataset.editing),data);delete f.dataset.editing;toast('Task updated')}else{state.tasks.unshift({...data,id:Date.now()});toast('Task created')}save();closeModal();render()});$('#newTaskBtn').onclick=()=>openModal();$('#myTaskCreate').onclick=()=>openModal();$('#closeModal').onclick=closeModal;$('#cancelModal').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};
$$('[data-view]').forEach(btn=>btn.onclick=()=>{$$('[data-view]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$$('.page-section').forEach(x=>x.classList.add('hidden'));$(`#${btn.dataset.view==='overview'?'overviewView':btn.dataset.view+'View'}`).classList.remove('hidden');$('#pageCrumb').textContent=btn.textContent.trim()});$('#inviteBtn').onclick=$('#inviteFromCard').onclick=()=>{navigator.clipboard?.writeText('NORTHSTAR-7Q2K');toast('Invite code copied: NORTHSTAR-7Q2K')};render();
